import {
  Box,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  Divider,
  Chip,
} from "@mui/material";
import {
  Dashboard as DashboardIcon,
  TrendingUp as ForecastIcon,
  Assessment as AnalyticsIcon,
  MonitorHeart as MonitorIcon,
  Speed as PerformanceIcon,
  CloudQueue as WeatherIcon,
  ListAlt as DataIcon,
  Settings as SettingsIcon,
  Help as HelpIcon,
} from "@mui/icons-material";
import { NavLink } from "react-router-dom";
import { ROUTES } from "../../routes/routes";
import logo from "../../assets/Eskom-logo-white.gif";

// NEW GROUPING - More logical organization
const navigation = {
  main: [
    {
      title: "Dashboard",
      icon: DashboardIcon,
      path: ROUTES.FORECAST,
      badge: null,
      description: "Overview & KPIs",
    },
  ],
  forecasting: [
    {
      title: "Forecast Generator",
      icon: ForecastIcon,
      path: ROUTES.FORECAST,
      badge: "LIVE",
      description: "Generate predictions",
    },
    {
      title: "Weather Intelligence",
      icon: WeatherIcon,
      path: ROUTES.FORECAST,
      badge: null,
      description: "Weather correlation",
    },
    {
      title: "Forecast Data",
      icon: DataIcon,
      path: ROUTES.FORECAST,
      badge: null,
      description: "Historical data",
    },
  ],
  analytics: [
    {
      title: "Model Performance",
      icon: PerformanceIcon,
      path: ROUTES.MODEL_PERFORMANCE,
      badge: null,
      description: "Accuracy metrics",
    },
    {
      title: "Analytics Dashboard",
      icon: AnalyticsIcon,
      path: ROUTES.MODEL_PERFORMANCE,
      badge: null,
      description: "Detailed analysis",
    },
  ],
  monitoring: [
    {
      title: "System Health",
      icon: MonitorIcon,
      path: ROUTES.INFERENCE,
      badge: null,
      description: "Pipeline status",
    },
    {
      title: "Activity Monitor",
      icon: MonitorIcon,
      path: ROUTES.INFERENCE_MONITORING,
      badge: "NEW",
      description: "Live tracking",
    },
  ],
};

const DashboardSidebar = () => {
  return (
    <Box
      sx={{
        width: 280,
        height: "100vh",
        bgcolor: "#003DA5", // Eskom Blue
        color: "white",
        display: "flex",
        flexDirection: "column",
        borderRight: "1px solid rgba(255, 255, 255, 0.1)",
        position: "sticky",
        top: 0,
      }}
    >
      {/* LOGO & BRANDING */}
      <Box
        sx={{
          p: 3,
          borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
        }}
      >
        <Box
          component="img"
          src={logo}
          alt="Eskom"
          sx={{
            width: "100%",
            maxWidth: 160,
            mb: 1,
          }}
        />
        <Typography
          variant="caption"
          sx={{
            color: "#FFD100", // Eskom Yellow
            fontWeight: 700,
            fontSize: "0.75rem",
            letterSpacing: "0.5px",
          }}
        >
          FORECAST CONTROL CENTER
        </Typography>
      </Box>

      {/* NAVIGATION - Scrollable */}
      <Box
        sx={{
          flex: 1,
          overflow: "auto",
          py: 2,
          "&::-webkit-scrollbar": {
            width: "6px",
          },
          "&::-webkit-scrollbar-track": {
            background: "rgba(255, 255, 255, 0.05)",
          },
          "&::-webkit-scrollbar-thumb": {
            background: "rgba(255, 255, 255, 0.2)",
            borderRadius: "3px",
          },
        }}
      >
        {/* MAIN */}
        <Box px={2}>
          <Typography
            variant="overline"
            sx={{
              color: "rgba(255, 255, 255, 0.5)",
              fontSize: "0.65rem",
              fontWeight: 800,
              px: 2,
              display: "block",
              mb: 1,
            }}
          >
            MAIN
          </Typography>
          <List disablePadding>
            {navigation.main.map((item) => {
              const Icon = item.icon;
              return (
                <ListItemButton
                  key={item.path + item.title}
                  component={NavLink}
                  to={item.path}
                  sx={{
                    borderRadius: 2,
                    mb: 0.5,
                    py: 1.5,
                    "&.active": {
                      bgcolor: "#FFD100", // Eskom Yellow
                      color: "#003DA5",
                      fontWeight: 700,
                      "& .MuiListItemIcon-root": {
                        color: "#003DA5",
                      },
                    },
                    "&:hover": {
                      bgcolor: "rgba(255, 255, 255, 0.1)",
                    },
                  }}
                >
                  <ListItemIcon sx={{ color: "inherit", minWidth: 40 }}>
                    <Icon />
                  </ListItemIcon>
                  <ListItemText
                    primary={item.title}
                    secondary={item.description}
                    primaryTypographyProps={{
                      fontSize: "0.875rem",
                      fontWeight: 600,
                    }}
                    secondaryTypographyProps={{
                      fontSize: "0.7rem",
                      color: "rgba(255, 255, 255, 0.6)",
                    }}
                  />
                  {item.badge && (
                    <Chip
                      label={item.badge}
                      size="small"
                      sx={{
                        height: 20,
                        fontSize: "0.625rem",
                        fontWeight: 800,
                        bgcolor: "#4CAF50",
                        color: "white",
                      }}
                    />
                  )}
                </ListItemButton>
              );
            })}
          </List>
        </Box>

        <Divider sx={{ my: 2, borderColor: "rgba(255, 255, 255, 0.1)" }} />

        {/* FORECASTING */}
        <Box px={2}>
          <Typography
            variant="overline"
            sx={{
              color: "rgba(255, 255, 255, 0.5)",
              fontSize: "0.65rem",
              fontWeight: 800,
              px: 2,
              display: "block",
              mb: 1,
            }}
          >
            FORECASTING
          </Typography>
          <List disablePadding>
            {navigation.forecasting.map((item) => {
              const Icon = item.icon;
              return (
                <ListItemButton
                  key={item.path + item.title}
                  component={NavLink}
                  to={item.path}
                  sx={{
                    borderRadius: 2,
                    mb: 0.5,
                    py: 1.5,
                    "&.active": {
                      bgcolor: "#FFD100",
                      color: "#003DA5",
                      fontWeight: 700,
                      "& .MuiListItemIcon-root": {
                        color: "#003DA5",
                      },
                    },
                    "&:hover": {
                      bgcolor: "rgba(255, 255, 255, 0.1)",
                    },
                  }}
                >
                  <ListItemIcon sx={{ color: "inherit", minWidth: 40 }}>
                    <Icon />
                  </ListItemIcon>
                  <ListItemText
                    primary={item.title}
                    secondary={item.description}
                    primaryTypographyProps={{
                      fontSize: "0.875rem",
                      fontWeight: 600,
                    }}
                    secondaryTypographyProps={{
                      fontSize: "0.7rem",
                      color: "rgba(255, 255, 255, 0.6)",
                    }}
                  />
                  {item.badge && (
                    <Chip
                      label={item.badge}
                      size="small"
                      sx={{
                        height: 20,
                        fontSize: "0.625rem",
                        fontWeight: 800,
                        bgcolor: "#4CAF50",
                        color: "white",
                      }}
                    />
                  )}
                </ListItemButton>
              );
            })}
          </List>
        </Box>

        <Divider sx={{ my: 2, borderColor: "rgba(255, 255, 255, 0.1)" }} />

        {/* ANALYTICS */}
        <Box px={2}>
          <Typography
            variant="overline"
            sx={{
              color: "rgba(255, 255, 255, 0.5)",
              fontSize: "0.65rem",
              fontWeight: 800,
              px: 2,
              display: "block",
              mb: 1,
            }}
          >
            ANALYTICS
          </Typography>
          <List disablePadding>
            {navigation.analytics.map((item) => {
              const Icon = item.icon;
              return (
                <ListItemButton
                  key={item.path + item.title}
                  component={NavLink}
                  to={item.path}
                  sx={{
                    borderRadius: 2,
                    mb: 0.5,
                    py: 1.5,
                    "&.active": {
                      bgcolor: "#FFD100",
                      color: "#003DA5",
                      fontWeight: 700,
                      "& .MuiListItemIcon-root": {
                        color: "#003DA5",
                      },
                    },
                    "&:hover": {
                      bgcolor: "rgba(255, 255, 255, 0.1)",
                    },
                  }}
                >
                  <ListItemIcon sx={{ color: "inherit", minWidth: 40 }}>
                    <Icon />
                  </ListItemIcon>
                  <ListItemText
                    primary={item.title}
                    secondary={item.description}
                    primaryTypographyProps={{
                      fontSize: "0.875rem",
                      fontWeight: 600,
                    }}
                    secondaryTypographyProps={{
                      fontSize: "0.7rem",
                      color: "rgba(255, 255, 255, 0.6)",
                    }}
                  />
                  {item.badge && (
                    <Chip
                      label={item.badge}
                      size="small"
                      sx={{
                        height: 20,
                        fontSize: "0.625rem",
                        fontWeight: 800,
                        bgcolor: "#4CAF50",
                        color: "white",
                      }}
                    />
                  )}
                </ListItemButton>
              );
            })}
          </List>
        </Box>

        <Divider sx={{ my: 2, borderColor: "rgba(255, 255, 255, 0.1)" }} />

        {/* MONITORING */}
        <Box px={2}>
          <Typography
            variant="overline"
            sx={{
              color: "rgba(255, 255, 255, 0.5)",
              fontSize: "0.65rem",
              fontWeight: 800,
              px: 2,
              display: "block",
              mb: 1,
            }}
          >
            MONITORING
          </Typography>
          <List disablePadding>
            {navigation.monitoring.map((item) => {
              const Icon = item.icon;
              return (
                <ListItemButton
                  key={item.path + item.title}
                  component={NavLink}
                  to={item.path}
                  sx={{
                    borderRadius: 2,
                    mb: 0.5,
                    py: 1.5,
                    "&.active": {
                      bgcolor: "#FFD100",
                      color: "#003DA5",
                      fontWeight: 700,
                      "& .MuiListItemIcon-root": {
                        color: "#003DA5",
                      },
                    },
                    "&:hover": {
                      bgcolor: "rgba(255, 255, 255, 0.1)",
                    },
                  }}
                >
                  <ListItemIcon sx={{ color: "inherit", minWidth: 40 }}>
                    <Icon />
                  </ListItemIcon>
                  <ListItemText
                    primary={item.title}
                    secondary={item.description}
                    primaryTypographyProps={{
                      fontSize: "0.875rem",
                      fontWeight: 600,
                    }}
                    secondaryTypographyProps={{
                      fontSize: "0.7rem",
                      color: "rgba(255, 255, 255, 0.6)",
                    }}
                  />
                  {item.badge && (
                    <Chip
                      label={item.badge}
                      size="small"
                      sx={{
                        height: 20,
                        fontSize: "0.625rem",
                        fontWeight: 800,
                        bgcolor: "#FFD100",
                        color: "#003DA5",
                      }}
                    />
                  )}
                </ListItemButton>
              );
            })}
          </List>
        </Box>
      </Box>

      {/* FOOTER - System Status */}
      <Box
        sx={{
          p: 2,
          borderTop: "1px solid rgba(255, 255, 255, 0.1)",
        }}
      >
        <Box
          sx={{
            bgcolor: "rgba(76, 175, 80, 0.15)",
            border: "1px solid #4CAF50",
            borderRadius: 2,
            p: 1.5,
            mb: 1,
          }}
        >
          <Box display="flex" alignItems="center" gap={1}>
            <Box
              sx={{
                width: 8,
                height: 8,
                borderRadius: "50%",
                bgcolor: "#4CAF50",
                animation: "pulse 2s infinite",
                "@keyframes pulse": {
                  "0%, 100%": { opacity: 1 },
                  "50%": { opacity: 0.5 },
                },
              }}
            />
            <Typography variant="caption" fontWeight={700} color="#4CAF50">
              ALL SYSTEMS ONLINE
            </Typography>
          </Box>
        </Box>

        <ListItemButton
          sx={{
            borderRadius: 2,
            "&:hover": {
              bgcolor: "rgba(255, 255, 255, 0.1)",
            },
          }}
        >
          <ListItemIcon sx={{ color: "white", minWidth: 40 }}>
            <SettingsIcon />
          </ListItemIcon>
          <ListItemText
            primary="Settings"
            primaryTypographyProps={{
              fontSize: "0.875rem",
              fontWeight: 600,
            }}
          />
        </ListItemButton>

        <ListItemButton
          sx={{
            borderRadius: 2,
            "&:hover": {
              bgcolor: "rgba(255, 255, 255, 0.1)",
            },
          }}
        >
          <ListItemIcon sx={{ color: "white", minWidth: 40 }}>
            <HelpIcon />
          </ListItemIcon>
          <ListItemText
            primary="Help & Support"
            primaryTypographyProps={{
              fontSize: "0.875rem",
              fontWeight: 600,
            }}
          />
        </ListItemButton>
      </Box>
    </Box>
  );
};

export default DashboardSidebar;
